
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_sfat_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_sfat_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.085992301717071e+00, -4.004106253963585e+00, -3.889451225016105e+00, -3.730806093422828e+00, -3.515004901508395e+00, -3.228551577175672e+00, -2.861365282809352e+00, -2.413299906108737e+00, -1.901858563142037e+00, -1.362577847258573e+00, -8.430900550316356e-01, -5.240785471404044e-01, -4.326543945193244e-01, -3.314428221682083e-01, -2.026344028850283e-01, -8.616844361442827e-02, -1.732673209799279e-02, -8.824405131606568e-04, -8.886754580968208e-06, -1.242289349578351e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


